//! With `shell`, the Tauri plugin's permissions: one `allow-`/`deny-` pair
//! per command, written under `permissions/autogenerated/`, and handed to
//! the desktop's build through `links`. The list is every command either
//! feature can register, so the files don't change with the features on.

#[cfg(feature = "shell")]
const COMMANDS: &[&str] = &[
    "status",
    "reset_plan",
    "reset_run",
    "demo_open",
    "demo_leave",
    "demo_reset",
    "demo_load_pack",
];

fn main() {
    #[cfg(feature = "shell")]
    tauri_plugin::Builder::new(COMMANDS).build();
}
